//! `OpenFlow` protocol implementation for OVS.
//!
//! Provides:
//! - `OpenFlow` message encoding/decoding
//! - Match field builder
//! - Action types
//! - Flow modification
//! - Virtual connection (`VConn`) abstraction

mod action;
mod error;
mod flow;
mod flow_monitor;
mod instruction;
mod match_fields;
mod message;
mod multipart;
pub mod ndp;
pub mod oxm;
mod packet_in;
mod packet_out;
mod vconn;

pub use action::{nxm, Action, ActionList, LearnSpec, NatConfig, NxLearn, OutputPort, CT_COMMIT};
pub use error::{Error, OfError, OfErrorType};
pub use flow::{Flow, FlowCommand, FlowFlags, FlowStats};
pub use flow_monitor::{monitor_flags, FlowMonitorRequest, FlowUpdate, FlowUpdateEvent, FlowUpdateFull};
pub use instruction::{Instruction, InstructionList};
pub use match_fields::Match;
pub use message::{Header, Message, MessageType};
pub use multipart::{FlowStatsEntry, FlowStatsRequest, MultipartType};
pub use packet_in::{PacketIn, PacketInReason, OFP_NO_BUFFER};
pub use packet_out::{PacketOut, OFPP_CONTROLLER, OFPP_ANY};
pub use vconn::VConn;

pub type Result<T> = std::result::Result<T, Error>;

/// OpenFlow protocol versions.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
#[repr(u8)]
pub enum Version {
    /// OpenFlow 1.0
    Of10 = 0x01,
    /// OpenFlow 1.1
    Of11 = 0x02,
    /// OpenFlow 1.2
    Of12 = 0x03,
    /// OpenFlow 1.3
    Of13 = 0x04,
    /// OpenFlow 1.4
    Of14 = 0x05,
    /// OpenFlow 1.5
    Of15 = 0x06,
}

impl Version {
    /// Get the wire format version number.
    pub fn wire_version(self) -> u8 {
        self as u8
    }
}

impl TryFrom<u8> for Version {
    type Error = Error;

    fn try_from(v: u8) -> Result<Self> {
        match v {
            0x01 => Ok(Self::Of10),
            0x02 => Ok(Self::Of11),
            0x03 => Ok(Self::Of12),
            0x04 => Ok(Self::Of13),
            0x05 => Ok(Self::Of14),
            0x06 => Ok(Self::Of15),
            _ => Err(Error::UnsupportedVersion(v)),
        }
    }
}

//! OpenFlow message types.

use bytes::{Buf, BufMut, Bytes, BytesMut};

use crate::{Error, Result, Version};

/// OpenFlow message header (8 bytes).
#[derive(Debug, Clone, Copy)]
pub struct Header {
    /// Protocol version
    pub version: Version,
    /// Message type
    pub msg_type: MessageType,
    /// Total message length (including header)
    pub length: u16,
    /// Transaction ID
    pub xid: u32,
}

impl Header {
    /// Header size in bytes.
    pub const SIZE: usize = 8;

    /// Encode the header to bytes.
    pub fn encode(&self, buf: &mut BytesMut) {
        buf.put_u8(self.version.wire_version());
        buf.put_u8(self.msg_type as u8);
        buf.put_u16(self.length);
        buf.put_u32(self.xid);
    }

    /// Decode a header from bytes.
    pub fn decode(buf: &mut Bytes) -> Result<Self> {
        if buf.remaining() < Self::SIZE {
            return Err(Error::Parse("header too short".into()));
        }

        let version = Version::try_from(buf.get_u8())?;
        let msg_type = MessageType::try_from(buf.get_u8())?;
        let length = buf.get_u16();
        let xid = buf.get_u32();

        Ok(Self {
            version,
            msg_type,
            length,
            xid,
        })
    }
}

/// OpenFlow message types.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum MessageType {
    // Symmetric messages
    /// Hello message
    Hello = 0,
    /// Error message
    Error = 1,
    /// Echo request
    EchoRequest = 2,
    /// Echo reply
    EchoReply = 3,
    /// Experimenter message
    Experimenter = 4,

    // Controller-to-switch messages
    /// Features request
    FeaturesRequest = 5,
    /// Features reply
    FeaturesReply = 6,
    /// Get config request
    GetConfigRequest = 7,
    /// Get config reply
    GetConfigReply = 8,
    /// Set config
    SetConfig = 9,

    // Async messages
    /// Packet in
    PacketIn = 10,
    /// Flow removed
    FlowRemoved = 11,
    /// Port status
    PortStatus = 12,

    // Controller-to-switch messages
    /// Packet out
    PacketOut = 13,
    /// Flow mod
    FlowMod = 14,
    /// Group mod (OF 1.1+)
    GroupMod = 15,
    /// Port mod
    PortMod = 16,
    /// Table mod (OF 1.1+)
    TableMod = 17,

    // Multipart messages (OF 1.3+)
    /// Multipart request
    MultipartRequest = 18,
    /// Multipart reply
    MultipartReply = 19,

    // Barrier
    /// Barrier request
    BarrierRequest = 20,
    /// Barrier reply
    BarrierReply = 21,

    // Controller role (OF 1.2+)
    /// Role request
    RoleRequest = 24,
    /// Role reply
    RoleReply = 25,

    // Async config (OF 1.3+)
    /// Get async request
    GetAsyncRequest = 26,
    /// Get async reply
    GetAsyncReply = 27,
    /// Set async
    SetAsync = 28,

    // Meters (OF 1.3+)
    /// Meter mod
    MeterMod = 29,

    // Bundle (OF 1.4+)
    /// Bundle control
    BundleControl = 33,
    /// Bundle add message
    BundleAddMessage = 34,
}

impl TryFrom<u8> for MessageType {
    type Error = Error;

    fn try_from(v: u8) -> Result<Self> {
        match v {
            0 => Ok(Self::Hello),
            1 => Ok(Self::Error),
            2 => Ok(Self::EchoRequest),
            3 => Ok(Self::EchoReply),
            4 => Ok(Self::Experimenter),
            5 => Ok(Self::FeaturesRequest),
            6 => Ok(Self::FeaturesReply),
            7 => Ok(Self::GetConfigRequest),
            8 => Ok(Self::GetConfigReply),
            9 => Ok(Self::SetConfig),
            10 => Ok(Self::PacketIn),
            11 => Ok(Self::FlowRemoved),
            12 => Ok(Self::PortStatus),
            13 => Ok(Self::PacketOut),
            14 => Ok(Self::FlowMod),
            15 => Ok(Self::GroupMod),
            16 => Ok(Self::PortMod),
            17 => Ok(Self::TableMod),
            18 => Ok(Self::MultipartRequest),
            19 => Ok(Self::MultipartReply),
            20 => Ok(Self::BarrierRequest),
            21 => Ok(Self::BarrierReply),
            24 => Ok(Self::RoleRequest),
            25 => Ok(Self::RoleReply),
            26 => Ok(Self::GetAsyncRequest),
            27 => Ok(Self::GetAsyncReply),
            28 => Ok(Self::SetAsync),
            29 => Ok(Self::MeterMod),
            33 => Ok(Self::BundleControl),
            34 => Ok(Self::BundleAddMessage),
            _ => Err(Error::InvalidMessage(format!("unknown message type: {v}"))),
        }
    }
}

/// A complete OpenFlow message.
#[derive(Debug)]
pub struct Message {
    /// Message header
    pub header: Header,
    /// Message body
    pub body: Bytes,
}

impl Message {
    /// Create a new message.
    pub fn new(version: Version, msg_type: MessageType, xid: u32, body: Bytes) -> Self {
        let length = (Header::SIZE + body.len()) as u16;
        Self {
            header: Header {
                version,
                msg_type,
                length,
                xid,
            },
            body,
        }
    }

    /// Encode the message to bytes.
    pub fn encode(&self) -> BytesMut {
        let mut buf = BytesMut::with_capacity(self.header.length as usize);
        self.header.encode(&mut buf);
        buf.extend_from_slice(&self.body);
        buf
    }
}

//! Transport layer for OVSDB and `OpenFlow` connections.
//!
//! Provides async stream abstractions over:
//! - Unix domain sockets
//! - TCP sockets
//! - TLS-encrypted TCP connections
//!
//! Also includes reconnection state machine logic.

mod address;
mod error;
mod reconnect;
mod stream;

pub use address::Address;
pub use error::Error;
pub use reconnect::Reconnect;
pub use stream::Stream;

pub type Result<T> = std::result::Result<T, Error>;

//! Async stream abstraction.

use std::pin::Pin;
use std::task::{Context, Poll};

use tokio::io::{AsyncRead, AsyncWrite, ReadBuf};
use tokio::net::{TcpStream, UnixStream};

use crate::{Address, Error, Result};

/// A transport stream that can be Unix, TCP, or TLS.
pub enum Stream {
    /// Unix domain socket
    Unix(UnixStream),
    /// TCP socket
    Tcp(TcpStream),
    /// TLS over TCP
    Tls(Box<tokio_rustls::client::TlsStream<TcpStream>>),
}

impl Stream {
    /// Connect to the given address.
    ///
    /// # Errors
    ///
    /// Returns an error if the connection fails or TLS is requested but not yet implemented.
    pub async fn connect(addr: &Address) -> Result<Self> {
        match addr {
            Address::Unix(path) => {
                let stream = UnixStream::connect(path).await?;
                Ok(Self::Unix(stream))
            }
            Address::Tcp { host, port } => {
                let stream = TcpStream::connect(format!("{host}:{port}")).await?;
                Ok(Self::Tcp(stream))
            }
            Address::Tls { host: _, port: _ } => {
                // TODO: Implement TLS connection
                Err(Error::Tls("TLS not yet implemented".into()))
            }
        }
    }
}

impl AsyncRead for Stream {
    fn poll_read(
        self: Pin<&mut Self>,
        cx: &mut Context<'_>,
        buf: &mut ReadBuf<'_>,
    ) -> Poll<std::io::Result<()>> {
        match self.get_mut() {
            Self::Unix(s) => Pin::new(s).poll_read(cx, buf),
            Self::Tcp(s) => Pin::new(s).poll_read(cx, buf),
            Self::Tls(s) => Pin::new(s.as_mut()).poll_read(cx, buf),
        }
    }
}

impl AsyncWrite for Stream {
    fn poll_write(
        self: Pin<&mut Self>,
        cx: &mut Context<'_>,
        buf: &[u8],
    ) -> Poll<std::io::Result<usize>> {
        match self.get_mut() {
            Self::Unix(s) => Pin::new(s).poll_write(cx, buf),
            Self::Tcp(s) => Pin::new(s).poll_write(cx, buf),
            Self::Tls(s) => Pin::new(s.as_mut()).poll_write(cx, buf),
        }
    }

    fn poll_flush(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<std::io::Result<()>> {
        match self.get_mut() {
            Self::Unix(s) => Pin::new(s).poll_flush(cx),
            Self::Tcp(s) => Pin::new(s).poll_flush(cx),
            Self::Tls(s) => Pin::new(s.as_mut()).poll_flush(cx),
        }
    }

    fn poll_shutdown(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<std::io::Result<()>> {
        match self.get_mut() {
            Self::Unix(s) => Pin::new(s).poll_shutdown(cx),
            Self::Tcp(s) => Pin::new(s).poll_shutdown(cx),
            Self::Tls(s) => Pin::new(s.as_mut()).poll_shutdown(cx),
        }
    }
}

//! JSON-RPC 1.0 connection handling for OVSDB.
//!
//! This module implements JSON-RPC communication with OVSDB servers.
//!
//! # Important Implementation Detail
//!
//! OVSDB servers do **not** send newlines after JSON responses. Instead, this
//! implementation uses brace-depth tracking to detect complete JSON objects.
//! The parser tracks `{` and `}` characters (respecting string contents and escapes)
//! to determine when a complete message has been received.

use std::collections::VecDeque;
use std::sync::atomic::{AtomicU64, Ordering};

use serde_json::Value;
use tokio::io::{AsyncReadExt, AsyncWriteExt, BufWriter};

use rovs_transport::Stream;

use crate::{Error, Message, Request, Response, Result, RpcId};

/// A JSON-RPC connection over a transport stream.
///
/// Handles request/response matching and buffers server notifications
/// received while waiting for responses.
pub struct Connection {
    reader: tokio::io::ReadHalf<Stream>,
    writer: BufWriter<tokio::io::WriteHalf<Stream>>,
    read_buf: Vec<u8>,
    next_id: AtomicU64,
    /// Pending notifications from server (received while waiting for response)
    pending_notifications: VecDeque<Request>,
}

impl Connection {
    /// Create a new connection from a transport stream.
    ///
    /// The stream is split into read/write halves for concurrent I/O.
    pub fn new(stream: Stream) -> Self {
        let (read_half, write_half) = tokio::io::split(stream);
        Self {
            reader: read_half,
            writer: BufWriter::new(write_half),
            read_buf: Vec::with_capacity(4096),
            next_id: AtomicU64::new(1),
            pending_notifications: VecDeque::new(),
        }
    }

    /// Get the next request ID.
    pub fn next_id(&self) -> u64 {
        self.next_id.fetch_add(1, Ordering::SeqCst)
    }

    /// Send a request and wait for the matching response.
    ///
    /// Any notifications received while waiting are buffered and can be
    /// retrieved via [`pop_notification`](Self::pop_notification).
    ///
    /// Returns the result value, or an error if the RPC failed.
    pub async fn transact(&mut self, method: &str, params: Value) -> Result<Value> {
        let id = self.next_id();
        let request = Request::new(method, params, id);

        self.send_message(&Message::Request(request)).await?;
        let response = self.recv_response(id).await?;

        if let Some(error) = response.error {
            return Err(Error::Rpc(error));
        }

        Ok(response.result.unwrap_or(Value::Null))
    }

    /// Send a notification (no response expected).
    pub async fn notify(&mut self, method: &str, params: Value) -> Result<()> {
        let request = Request::notification(method, params);
        self.send_message(&Message::Request(request)).await
    }

    /// Send a message.
    pub async fn send_message(&mut self, msg: &Message) -> Result<()> {
        let json = serde_json::to_string(msg)?;
        tracing::debug!("TX: {}", json);
        self.writer.write_all(json.as_bytes()).await?;
        self.writer.write_all(b"\n").await?;
        self.writer.flush().await?;
        Ok(())
    }

    /// Receive a response, buffering any notifications received in the meantime.
    async fn recv_response(&mut self, expected_id: u64) -> Result<Response> {
        let expected = RpcId::Number(expected_id);
        loop {
            let msg = self.recv_message().await?;

            match msg {
                Message::Response(resp) => {
                    if resp.id != expected {
                        return Err(Error::UnexpectedId {
                            expected: expected_id,
                            got: resp.id.as_u64().unwrap_or(0),
                        });
                    }
                    return Ok(resp);
                }
                Message::Request(req) => {
                    // Server notification - buffer it for later processing
                    tracing::debug!("Buffering notification: {}", req.method);
                    self.pending_notifications.push_back(req);
                }
            }
        }
    }

    /// Receive a single message from the connection.
    ///
    /// Uses brace-depth tracking to detect complete JSON objects since
    /// OVSDB servers don't send newlines after responses. Handles:
    /// - Nested JSON objects
    /// - Strings containing braces
    /// - Escaped characters within strings
    ///
    /// Returns either a [`Request`] (notification from server) or
    /// [`Response`] (reply to our request).
    pub async fn recv_message(&mut self) -> Result<Message> {
        tracing::debug!("Waiting to receive message...");

        // Read bytes until we have a complete JSON object
        let mut depth = 0i32;
        let mut in_string = false;
        let mut escape_next = false;
        let mut json_start = None;

        loop {
            // Try to parse from existing buffer first
            for (i, &byte) in self.read_buf.iter().enumerate() {
                if json_start.is_none() && byte == b'{' {
                    json_start = Some(i);
                }

                if json_start.is_some() {
                    if escape_next {
                        escape_next = false;
                        continue;
                    }

                    match byte {
                        b'\\' if in_string => escape_next = true,
                        b'"' => in_string = !in_string,
                        b'{' if !in_string => depth += 1,
                        b'}' if !in_string => {
                            depth -= 1;
                            if depth == 0 {
                                // Found complete JSON object
                                let start = json_start.unwrap();
                                let json_bytes = &self.read_buf[start..=i];
                                let json_str = String::from_utf8_lossy(json_bytes);
                                tracing::debug!("RX: {}", json_str);

                                let msg: Message = serde_json::from_slice(json_bytes)?;

                                // Remove consumed bytes from buffer
                                self.read_buf.drain(..=i);

                                return Ok(msg);
                            }
                        }
                        _ => {}
                    }
                }
            }

            // Need more data - reset parsing state since we'll re-scan from start
            depth = 0;
            in_string = false;
            escape_next = false;
            json_start = None;

            let mut buf = [0u8; 4096];
            tracing::debug!("Reading more data...");
            let n = self.reader.read(&mut buf).await?;
            tracing::debug!("Read {} bytes", n);

            if n == 0 {
                return Err(Error::ConnectionClosed);
            }

            self.read_buf.extend_from_slice(&buf[..n]);
            tracing::debug!("Buffer now has {} bytes", self.read_buf.len());
        }
    }

    /// Check if there are buffered notifications from the server.
    ///
    /// Notifications received while waiting for a response are buffered here.
    pub fn has_pending_notifications(&self) -> bool {
        !self.pending_notifications.is_empty()
    }

    /// Get the count of pending notifications.
    pub fn pending_notification_count(&self) -> usize {
        self.pending_notifications.len()
    }

    /// Pop the next buffered notification (FIFO order).
    ///
    /// Returns `None` if no notifications are pending.
    pub fn pop_notification(&mut self) -> Option<Request> {
        self.pending_notifications.pop_front()
    }

    /// Drain all buffered notifications, returning an iterator.
    ///
    /// Clears the notification buffer and yields all pending notifications.
    pub fn drain_notifications(&mut self) -> impl Iterator<Item = Request> + '_ {
        self.pending_notifications.drain(..)
    }
}

//! OVSDB client - manages connection, schema, and IDL.

use serde_json::{Value, json};
use uuid::Uuid;

use rovs_jsonrpc::Connection;
use rovs_transport::{Address, Stream};

use crate::{DbSchema, Error, Idl, IdlState, Result, Transaction};

/// Monitor protocol version.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MonitorVersion {
    /// Original monitor (OVSDB_UPDATE)
    V1,
    /// monitor_cond (OVSDB_UPDATE2)
    V2,
    /// monitor_cond_since (OVSDB_UPDATE3)
    V3,
}

/// OVSDB client configuration.
#[derive(Debug, Clone)]
pub struct ClientConfig {
    /// Database name to connect to
    pub database: String,
    /// Tables to monitor (None = all tables)
    pub tables: Option<Vec<String>>,
    /// Monitor protocol version to use
    pub monitor_version: MonitorVersion,
    /// Leader-only mode for clustered OVSDB
    pub leader_only: bool,
}

impl Default for ClientConfig {
    fn default() -> Self {
        Self {
            database: "Open_vSwitch".to_owned(),
            tables: None,
            monitor_version: MonitorVersion::V1,
            leader_only: false,
        }
    }
}

impl ClientConfig {
    /// Create config for Open_vSwitch database.
    pub fn open_vswitch() -> Self {
        Self::default()
    }

    /// Set the database name.
    pub fn database(mut self, name: impl Into<String>) -> Self {
        self.database = name.into();
        self
    }

    /// Set specific tables to monitor.
    pub fn tables(mut self, tables: Vec<String>) -> Self {
        self.tables = Some(tables);
        self
    }

    /// Set monitor version.
    pub fn monitor_version(mut self, version: MonitorVersion) -> Self {
        self.monitor_version = version;
        self
    }
}

/// OVSDB client.
///
/// Manages the connection to an OVSDB server, fetches the schema,
/// and maintains an in-memory replica via the IDL.
pub struct Client {
    conn: Connection,
    config: ClientConfig,
    idl: Idl,
    monitor_id: Option<Uuid>,
}

impl Client {
    /// Connect to an OVSDB server.
    pub async fn connect(addr: &str) -> Result<Self> {
        Self::connect_with_config(addr, ClientConfig::default()).await
    }

    /// Connect to an OVSDB server with custom configuration.
    pub async fn connect_with_config(addr: &str, config: ClientConfig) -> Result<Self> {
        let address: Address = addr.parse()?;
        let stream = Stream::connect(&address).await?;
        let conn = Connection::new(stream);

        let mut client = Self {
            conn,
            config,
            idl: Idl::new(),
            monitor_id: None,
        };

        // Initialize: fetch schema and start monitoring
        client.initialize().await?;

        Ok(client)
    }

    /// Get the IDL (in-memory database replica).
    ///
    /// The IDL contains all monitored tables and rows. Use it to query
    /// the current state without making RPC calls.
    ///
    /// # Example
    ///
    /// ```ignore
    /// for bridge in client.idl().rows("Bridge") {
    ///     println!("Bridge: {}", bridge.get_string("name").unwrap_or("?"));
    /// }
    /// ```
    pub fn idl(&self) -> &Idl {
        &self.idl
    }

    /// Get a mutable reference to the IDL.
    ///
    /// Rarely needed; most operations use the immutable [`idl`](Self::idl).
    pub fn idl_mut(&mut self) -> &mut Idl {
        &mut self.idl
    }

    /// Get the database schema.
    ///
    /// The schema describes all tables and columns in the database.
    /// Returns `None` if the schema hasn't been loaded yet.
    pub fn schema(&self) -> Option<&DbSchema> {
        self.idl.schema()
    }

    /// Check if the client is connected and actively monitoring.
    ///
    /// Returns `true` after successful connection and monitor setup.
    pub fn is_connected(&self) -> bool {
        self.idl.state() == IdlState::Monitoring
    }

    /// Initialize the client: fetch schema and start monitoring.
    async fn initialize(&mut self) -> Result<()> {
        // Step 1: Fetch schema
        self.fetch_schema().await?;

        // Step 2: Start monitoring
        self.start_monitor().await?;

        Ok(())
    }

    /// Fetch the database schema.
    async fn fetch_schema(&mut self) -> Result<()> {
        tracing::debug!("Fetching schema for database: {}", self.config.database);

        let result = self
            .conn
            .transact("get_schema", json!([self.config.database]))
            .await?;

        let schema = DbSchema::from_json(&result)?;
        tracing::info!(
            "Loaded schema: {} v{} ({} tables)",
            schema.name,
            schema.version,
            schema.tables.len()
        );

        self.idl.set_schema(schema);
        Ok(())
    }

    /// Start monitoring the database.
    async fn start_monitor(&mut self) -> Result<()> {
        let schema = self
            .idl
            .schema()
            .ok_or_else(|| Error::Schema("schema not loaded".into()))?;

        // Build monitor request for each table
        let mut monitor_requests = serde_json::Map::new();

        let tables_to_monitor: Vec<&String> = match &self.config.tables {
            Some(tables) => tables.iter().collect(),
            None => schema.tables.keys().collect(),
        };

        for table_name in tables_to_monitor {
            if let Some(table_schema) = schema.tables.get(table_name) {
                // Request all columns for the table
                let columns: Vec<&String> = table_schema.columns.keys().collect();

                let table_monitor = json!({
                    "columns": columns,
                });

                monitor_requests.insert(table_name.clone(), table_monitor);
            }
        }

        let monitor_id = Uuid::new_v4();
        self.monitor_id = Some(monitor_id);

        // Choose monitor method based on version
        let (method, params) = match self.config.monitor_version {
            MonitorVersion::V1 => (
                "monitor",
                json!([
                    self.config.database,
                    monitor_id.to_string(),
                    monitor_requests
                ]),
            ),
            MonitorVersion::V2 => (
                "monitor_cond",
                json!([
                    self.config.database,
                    monitor_id.to_string(),
                    monitor_requests
                ]),
            ),
            MonitorVersion::V3 => (
                "monitor_cond_since",
                json!([
                    self.config.database,
                    monitor_id.to_string(),
                    monitor_requests,
                    "00000000-0000-0000-0000-000000000000" // last_txn_id
                ]),
            ),
        };

        tracing::debug!("Starting monitor with method: {}", method);

        let result = self.conn.transact(method, params).await?;

        // Process initial data
        self.process_monitor_reply(&result)?;
        self.idl.set_monitoring();

        tracing::info!("Monitoring started, {} tables", monitor_requests.len());

        Ok(())
    }

    /// Process the initial monitor reply.
    fn process_monitor_reply(&mut self, reply: &Value) -> Result<()> {
        match self.config.monitor_version {
            MonitorVersion::V1 => {
                // V1: reply is the table update directly
                self.idl.process_update(reply);
            }
            MonitorVersion::V2 | MonitorVersion::V3 => {
                // V2/V3: reply may have different structure
                // For V3, it's [found, last_txn_id, updates]
                if let Some(arr) = reply.as_array() {
                    if arr.len() >= 3 {
                        // V3 format
                        self.idl.process_update(&arr[2]);
                    } else {
                        self.idl.process_update(reply);
                    }
                } else {
                    self.idl.process_update(reply);
                }
            }
        }
        Ok(())
    }

    /// Process any pending update notifications (non-blocking).
    ///
    /// Drains buffered notifications and updates the IDL. Use this in
    /// event loops where you need to check for updates without blocking.
    ///
    /// Returns `true` if any updates were processed.
    ///
    /// For blocking behavior, use [`wait`](Self::wait) instead.
    pub async fn run(&mut self) -> Result<bool> {
        let mut updated = false;

        // Process any buffered notifications
        while let Some(notification) = self.conn.pop_notification() {
            if notification.method == "update"
                || notification.method == "update2"
                || notification.method == "update3"
            {
                if let Some(params) = notification.params.as_array() {
                    // params: [monitor_id, updates]
                    if params.len() >= 2 {
                        self.idl.process_update(&params[1]);
                        updated = true;
                    }
                }
            }
        }

        Ok(updated)
    }

    /// Wait for the next update from the server (blocking).
    ///
    /// Blocks until an OVSDB update notification is received, then updates
    /// the IDL and returns. Use this in a loop to continuously monitor changes.
    ///
    /// # Example
    ///
    /// ```ignore
    /// loop {
    ///     client.wait().await?;
    ///     println!("Update received, seqno: {}", client.idl().change_seqno());
    ///     // Process changes...
    /// }
    /// ```
    pub async fn wait(&mut self) -> Result<()> {
        use rovs_jsonrpc::Message;

        // First, check for buffered notifications from previous operations
        while let Some(notification) = self.conn.pop_notification() {
            if notification.method == "echo" {
                self.send_echo_reply(&notification.params, notification.id.as_ref()).await?;
                continue;
            }
            if let Some(updated) = self.process_notification(&notification) {
                if updated {
                    return Ok(());
                }
            }
        }

        // No buffered updates, wait for new messages
        loop {
            let msg = self.conn.recv_message().await?;

            match msg {
                Message::Request(req) => {
                    if req.method == "echo" {
                        self.send_echo_reply(&req.params, req.id.as_ref()).await?;
                        continue;
                    }
                    if let Some(updated) = self.process_notification(&req) {
                        if updated {
                            return Ok(());
                        }
                    }
                }
                Message::Response(_) => {
                    tracing::warn!("Received unexpected response");
                }
            }
        }
    }

    /// Process a notification from the server.
    ///
    /// Returns `Some(true)` if this was an update notification that was processed,
    /// `Some(false)` if it was handled but not an update, or `None` if unhandled.
    fn process_notification(&mut self, req: &rovs_jsonrpc::Request) -> Option<bool> {
        match req.method.as_str() {
            "update" | "update2" | "update3" => {
                if let Some(params) = req.params.as_array() {
                    if params.len() >= 2 {
                        self.idl.process_update(&params[1]);
                        return Some(true);
                    }
                }
                Some(false)
            }
            "echo" => {
                // Server echo request - handled asynchronously
                tracing::debug!("Received echo request from server");
                Some(false)
            }
            _ => {
                tracing::debug!("Unknown notification: {}", req.method);
                None
            }
        }
    }

    /// Send echo reply to server.
    async fn send_echo_reply(&mut self, params: &Value, id: Option<&rovs_jsonrpc::RpcId>) -> Result<()> {
        use rovs_jsonrpc::{Message, Response, RpcId};

        let response_id = id.cloned().unwrap_or_else(|| RpcId::String("echo".to_owned()));
        let response = Response::success(response_id, params.clone());
        self.conn.send_message(&Message::Response(response)).await?;
        Ok(())
    }

    /// Execute a raw transaction with operations as JSON.
    pub async fn transact(&mut self, operations: Value) -> Result<Value> {
        let params = if let Value::Array(mut arr) = operations {
            arr.insert(0, Value::String(self.config.database.clone()));
            Value::Array(arr)
        } else {
            json!([self.config.database, operations])
        };

        self.conn
            .transact("transact", params)
            .await
            .map_err(Into::into)
    }

    /// Commit a transaction.
    ///
    /// Sends the transaction to the server and processes the result.
    /// On success, the transaction's uuid_map will be populated with
    /// the actual UUIDs for any inserted rows.
    pub async fn commit(&mut self, txn: &mut Transaction) -> Result<bool> {
        if txn.is_empty() {
            return Ok(true);
        }

        // Build and send the transaction
        let params = txn.build();
        let result = self.conn.transact("transact", params).await?;

        // Process the result
        Ok(txn.process_result(&result))
    }

    /// Get the list of databases on the server.
    pub async fn list_dbs(&mut self) -> Result<Vec<String>> {
        let result = self.conn.transact("list_dbs", json!([])).await?;

        let dbs = result
            .as_array()
            .map(|arr| {
                arr.iter()
                    .filter_map(|v| v.as_str().map(String::from))
                    .collect()
            })
            .unwrap_or_default();

        Ok(dbs)
    }

    /// Cancel the current monitor and stop receiving updates.
    ///
    /// After cancellation, the IDL will no longer receive updates. You can
    /// start a new monitor by reconnecting.
    pub async fn cancel_monitor(&mut self) -> Result<()> {
        if let Some(monitor_id) = self.monitor_id.take() {
            self.conn
                .transact("monitor_cancel", json!([monitor_id.to_string()]))
                .await?;
        }
        Ok(())
    }
}

